import json
import re
from datetime import datetime
from collections import defaultdict

def parse_tutar(tutar_str):
    if isinstance(tutar_str, (int, float)):
        return float(tutar_str)

    # Temizleme
    s = str(tutar_str).replace('₺', '').replace('TL', '').strip()
    if not s:
        return None

    # Nokta ve virgül mantığı
    # hem . hem , varsa: . binlik, , ondalık
    if '.' in s and ',' in s:
        s = s.replace('.', '').replace(',', '.')
    # yalnız , varsa: ondalık
    elif ',' in s and '.' not in s:
        s = s.replace(',', '.')
    # yalnız . varsa
    elif '.' in s and ',' not in s:
        # noktadan sonra tam 3 rakam varsa binlik (örn: 1.234)
        parts = s.split('.')
        if len(parts) == 2 and len(parts[1]) == 3:
            s = s.replace('.', '')
        else:
            pass # zaten ondalık

    try:
        return float(s)
    except ValueError:
        return None

def parse_tarih(tarih_str):
    tarih_str = str(tarih_str).strip()
    formats = [
        ("%Y-%m-%d", r"^\d{4}-\d{2}-\d{2}$"),
        ("%Y/%m/%d", r"^\d{4}/\d{2}/\d{2}$"),
        ("%d.%m.%Y", r"^\d{2}\.\d{2}\.\d{4}$"),
    ]

    for fmt, pattern in formats:
        if re.match(pattern, tarih_str):
            try:
                return datetime.strptime(tarih_str, fmt)
            except ValueError:
                continue

    # Türkçe ay isimleri: "2 Nisan 2025"
    aylar_tr = {
        "Ocak": 1, "Şubat": 2, "Mart": 3, "Nisan": 4, "Mayıs": 5, "Haziran": 6,
